const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

// Prices below are exact in binary floating point, so totals can be compared
// with strict equality.

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('addItem', () => {
    it('adds a new item with its price and quantity', () => {
      cart.addItem('apple', 1.5, 2);

      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('merges the quantity when an item with the same name is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);

      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 5 }]);
    });

    it('accepts a price of zero for free items', () => {
      cart.addItem('sticker', 0, 1);

      assert.deepEqual(cart.items, [{ name: 'sticker', price: 0, quantity: 1 }]);
    });

    it('accepts non-ASCII item names', () => {
      cart.addItem('café ☕', 3, 1);

      assert.equal(cart.items[0].name, 'café ☕');
    });

    it('rejects a negative price instead of adding the item (bug 1)', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), {
        name: 'RangeError',
        message: /price/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('rejects a negative quantity instead of adding the item (bug 1)', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), {
        name: 'RangeError',
        message: /quantity/,
      });
      assert.deepEqual(cart.items, []);
    });

    it('rejects a negative quantity for an existing item instead of decreasing it (bug 1)', () => {
      cart.addItem('apple', 1, 2);

      assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
      assert.equal(cart.items[0].quantity, 2);
    });

    const invalidPrices = [
      { label: 'NaN', value: NaN, error: TypeError },
      { label: 'a numeric string', value: '5', error: TypeError },
      { label: 'undefined', value: undefined, error: TypeError },
      { label: 'Infinity', value: Infinity, error: RangeError },
    ];
    for (const { label, value, error } of invalidPrices) {
      it(`rejects ${label} as a price`, () => {
        assert.throws(() => cart.addItem('apple', value, 1), error);
        assert.deepEqual(cart.items, []);
      });
    }

    const invalidQuantities = [
      { label: 'zero', value: 0, error: RangeError },
      { label: 'a fractional number', value: 1.5, error: RangeError },
      { label: 'Infinity', value: Infinity, error: RangeError },
      { label: 'NaN', value: NaN, error: TypeError },
      { label: 'a numeric string', value: '2', error: TypeError },
      { label: 'undefined', value: undefined, error: TypeError },
    ];
    for (const { label, value, error } of invalidQuantities) {
      it(`rejects ${label} as a quantity`, () => {
        assert.throws(() => cart.addItem('apple', 1, value), error);
        assert.deepEqual(cart.items, []);
      });
    }

    const invalidNames = [
      { label: 'an empty string', value: '' },
      { label: 'a whitespace-only string', value: '   ' },
      { label: 'null', value: null },
      { label: 'a number', value: 42 },
    ];
    for (const { label, value } of invalidNames) {
      it(`rejects ${label} as a name`, () => {
        assert.throws(() => cart.addItem(value, 1, 1), TypeError);
        assert.deepEqual(cart.items, []);
      });
    }
  });

  describe('removeItem', () => {
    it('removes only the named item and leaves the others unchanged (bug 2)', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 2);
      cart.addItem('cherry', 3, 3);

      cart.removeItem('banana');

      assert.deepEqual(cart.items, [
        { name: 'apple', price: 1, quantity: 1 },
        { name: 'cherry', price: 3, quantity: 3 },
      ]);
    });

    it('removes the whole line regardless of quantity', () => {
      cart.addItem('apple', 1, 5);

      cart.removeItem('apple');

      assert.deepEqual(cart.items, []);
    });

    it('throws when the item is not in the cart and leaves the cart unchanged (bug 2)', () => {
      cart.addItem('apple', 1, 1);

      assert.throws(() => cart.removeItem('pear'), {
        name: 'Error',
        message: /"pear"/,
      });
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 1 }]);
    });

    it('throws when removing from an empty cart', () => {
      assert.throws(() => cart.removeItem('apple'), /not in the cart/);
    });

    it('matches names exactly, including case', () => {
      cart.addItem('Apple', 1, 1);

      assert.throws(() => cart.removeItem('apple'), /not in the cart/);
      assert.equal(cart.getItemCount(), 1);
    });
  });

  describe('getTotal', () => {
    it('returns 0 for an empty cart instead of reading past the last item (bug 3)', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('sums price times quantity across every item (bug 3)', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('banana', 0.25, 4);
      cart.addItem('cherry', 10, 1);

      assert.equal(cart.getTotal(), 14);
    });

    it('subtracts the discount from the total instead of adding it (bug 4)', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(10);

      assert.equal(cart.getTotal(), 180);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(100);

      assert.equal(cart.getTotal(), 0);
    });

    it('returns 0 for an empty cart with a discount applied', () => {
      cart.applyDiscount(50);

      assert.equal(cart.getTotal(), 0);
    });

    it('reflects items removed after the discount was applied', () => {
      cart.addItem('jacket', 200, 1);
      cart.addItem('hat', 40, 2);
      cart.applyDiscount(25);

      cart.removeItem('hat');

      assert.equal(cart.getTotal(), 150);
    });
  });

  describe('applyDiscount', () => {
    it('replaces an earlier discount rather than compounding it', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(50);
      cart.applyDiscount(10);

      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 180);
    });

    for (const percent of [0, 100]) {
      it(`accepts the boundary value ${percent}`, () => {
        cart.applyDiscount(percent);

        assert.equal(cart.discount, percent);
      });
    }

    it('rejects a discount above 100 (bug 5)', () => {
      assert.throws(() => cart.applyDiscount(150), {
        name: 'RangeError',
        message: /between 0 and 100/,
      });
      assert.equal(cart.discount, 0);
    });

    it('rejects a negative discount (bug 5)', () => {
      assert.throws(() => cart.applyDiscount(-10), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('rejects values just outside the range', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
    });

    const invalidDiscounts = [
      { label: 'Infinity', value: Infinity, error: RangeError },
      { label: 'NaN', value: NaN, error: TypeError },
      { label: 'a numeric string', value: '10', error: TypeError },
      { label: 'null', value: null, error: TypeError },
      { label: 'undefined', value: undefined, error: TypeError },
    ];
    for (const { label, value, error } of invalidDiscounts) {
      it(`rejects ${label} as a discount`, () => {
        assert.throws(() => cart.applyDiscount(value), error);
        assert.equal(cart.discount, 0);
      });
    }

    it('keeps the previous valid discount when an invalid one is rejected', () => {
      cart.addItem('jacket', 200, 1);
      cart.applyDiscount(10);

      assert.throws(() => cart.applyDiscount(150), RangeError);

      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 180);
    });
  });

  describe('getItemCount', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getItemCount(), 0);
    });

    it('counts distinct items, not their combined quantity', () => {
      cart.addItem('apple', 1, 3);
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 2, 1);

      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases when an item is removed', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);

      cart.removeItem('apple');

      assert.equal(cart.getItemCount(), 1);
    });
  });
});

