   * Adds an item, or increases the quantity if an item with the same name is
   * already in the cart (the existing price is kept).
   *
   * @throws {TypeError} if name is not a non-blank string, or price/quantity
   *   is not a number.
   * @throws {RangeError} if price is negative or not finite, or quantity is
   *   not a positive integer.
   */
  addItem(name, price, quantity) {
    if (typeof name !== 'string' || name.trim() === '') {
      throw new TypeError(`name must be a non-empty string, got ${formatValue(name)}`);
    }
    assertNumber(price, 'price');
    if (!Number.isFinite(price) || price < 0) {
      throw new RangeError(`price must be a finite number >= 0, got ${price}`);
    }
    assertNumber(quantity, 'quantity');
    if (!Number.isInteger(quantity) || quantity < 1) {
      throw new RangeError(`quantity must be a positive integer, got ${quantity}`);
    }

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes the item with this exact name, whatever its quantity.
   *
   * @throws {Error} if no item with that name is in the cart.
   */
  removeItem(name) {
    if (!this.items.some(i => i.name === name)) {
      throw new Error(`Cannot remove ${formatValue(name)}: item is not in the cart`);
    }
    this.items = this.items.filter(i => i.name !== name);
  }

  getTotal() {
    let total = 0;
    for (let i = 0; i < this.items.length; i++) {
      total += this.items[i].price * this.items[i].quantity;
    }
    return total - (total * this.discount / 100);
  }

  /**
   * Sets the percentage discount applied by getTotal, replacing any earlier
   * discount. On invalid input the current discount is left unchanged.
   *
   * @param {number} percent - 0 to 100 inclusive.
   * @throws {TypeError} if percent is not a number.
   * @throws {RangeError} if percent is outside 0-100.
