      throw new RangeError(
        `discount must be between ${MIN_DISCOUNT_PERCENT} and ${MAX_DISCOUNT_PERCENT}, got ${percent}`
      );
    }
    this.discount = percent;
  }

  getItemCount() {
    return this.items.length;
  }
}

